public TicketClassifierService(string dataPath)
{
    _mlContext = new MLContext(seed: 42);

    var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
        .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
        .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
        .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
        .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
        .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    // Cross-validate for metrics (works better with small datasets)
    var cvResults = _mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
    _metrics = new EvaluationMetrics
    {
        MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
        MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
        LogLoss = cvResults.Average(r => r.Metrics.LogLoss),
        LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction)
    };

    // Train on full dataset for production predictions
    _model = pipeline.Fit(dataView);
    _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);

    // Extract category labels in key order using VBuffer
    var transformedData = _model.Transform(dataView);
    var labelCol = transformedData.Schema["Label"];
    var keyValues = new VBuffer<ReadOnlyMemory<char>>();
    labelCol.GetKeyValues(ref keyValues);
    _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
}

